import * as C from './core.mjs';
import {matchLibrary,matchSummary,acceptCandidate} from './matching.mjs';
import {createApi} from './api.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings=C.defaultSettings(),entries=[],originals=new Map(),selected=new Set(),page=0,step=0,plan=null,results=[],controller=null,worker=null,bridge=null,authTimer=null;const cache=new Map(),publicAniList=createApi(),publicMyAnimeList=createApi({destination:'MyAnimeList'});
const option=(v,label,current)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;
const statusOptions=v=>C.statuses.map(s=>option(s,s==='Unknown'?'Keep original / unknown':C.labels[s],v)).join('');
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6000);$('status').textContent=message;}
function modal(title,html,actions=[]){$('modal-title').textContent=title;$('modal-content').innerHTML=html;$('modal-actions').replaceChildren();for(const [label,fn] of actions){const b=document.createElement('button');b.className='button primary';b.textContent=label;b.onclick=()=>Promise.resolve().then(fn).catch(e=>toast(e.message));$('modal-actions').append(b);}if(!$('modal').open)$('modal').showModal();}
$('close-modal').onclick=()=>$('modal').close();
function invalidate(){plan=null;$('import-button').disabled=true;$('plan-details').hidden=true;$('plan-stats').replaceChildren();$('plan-empty').hidden=false;}
function changed(){invalidate();C.markDuplicates(entries);render();}
function navigate(n){if(n&&!entries.length){toast('Choose a backup or sample first.');return;}step=n;document.querySelectorAll('.page').forEach((p,i)=>p.classList.toggle('active',i===n));document.querySelectorAll('nav [data-step]').forEach(b=>b.classList.toggle('active',+b.dataset.step===n));const titles=['Your library. A fresh start.','A little less repetition.','Make every match count.','Ready for a new chapter.'];$('page-title').textContent=titles[n];$('breadcrumb').textContent=['Select backup','Set your defaults','Review your library','Export & import'][n];$('eyebrow').textContent=`Step ${n+1} of 4`;$('page-description').textContent=['Bring the stories you love to the place you track them.','Choose your destination, score and reading defaults.','Review matches and progress before anything reaches your account.','Save your work, then preview every account change.'][n];render();}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>navigate(+b.dataset.step));
function syncSettings(){document.querySelector(`[name=destination][value=${settings.destination}]`).checked=true;$('default-status').innerHTML=statusOptions(settings.defaultStatus);$('score-scale').value=settings.scoreScale;$('default-score').value=settings.defaultScore;for(const [id,k] of [['preserve-chapters','preserveChapters'],['preserve-volumes','preserveVolumes'],['instant','instant']])$(id).checked=settings[k];$('policy').value=settings.policy;$('auto-match').checked=settings.autoMatch;$('missing-status').value=settings.missingStatus;$('existing-policy').value=settings.existingPolicy;$('secret-label').hidden=settings.destination!=='AniList';$('score-explanation').textContent='Scores are converted from your chosen scale: AniList uses whole numbers from 0–100; MyAnimeList uses whole numbers from 0–10. Converted scores round to the nearest whole number (7.5/10 becomes 75 or 8).';}
function readSettings(){settings.defaultStatus=$('default-status').value;settings.scoreScale=+$('score-scale').value;settings.defaultScore=+$('default-score').value;settings.preserveChapters=$('preserve-chapters').checked;settings.preserveVolumes=$('preserve-volumes').checked;settings.instant=$('instant').checked;settings.policy=$('policy').value;settings.autoMatch=$('auto-match').checked;settings.missingStatus=$('missing-status').value;settings.existingPolicy=$('existing-policy').value;C.convertScore(settings.defaultScore,settings.scoreScale,settings.destination);}
function filtered(){const a=C.filterEntries(entries,$('search').value,$('filter').value,settings,$('content-filter').value);return a.sort((a,b)=>$('sort').value==='chapters'?b.chapters-a.chapters:$('sort').value==='status'?a.status.localeCompare(b.status):a.title.localeCompare(b.title)*($('sort').value==='title-desc'?-1:1));}
function stats(target,values){$(target).innerHTML=values.map(([label,value])=>`<div class="stat"><span>${esc(label)}</span><strong>${value.toLocaleString()}</strong></div>`).join('');}
function render(){renderMatching();const included=entries.filter(e=>e.included),ready=C.prepareImportEntries(entries,settings).filter(e=>e.included&&!C.validate(e,settings).length);stats('review-stats',[['Library entries',entries.length],['Confirmed matches',included.filter(e=>e.matchConfirmed).length],['Ready to import',ready.length],['Needs attention',included.length-ready.length]]);const rows=filtered();page=Math.max(0,Math.min(page,Math.ceil(rows.length/50)-1));$('library-body').innerHTML=rows.slice(page*50,page*50+50).map(e=>`<tr data-key="${esc(e.key)}" class="${e.included?'':'excluded'}"><td><input type="checkbox" data-select aria-label="Select ${esc(e.title)}" ${selected.has(e.key)?'checked':''}></td><td><span class="title">${esc(e.title)}</span><small>${esc(e.contentRating==='Unknown'?'Unclassified':e.contentRating)} · ${esc(e.author||e.source||'Unknown source')}${e.possibleDuplicate?' · Possible duplicate':''}</small></td><td><select data-field="status" aria-label="Status for ${esc(e.title)}">${statusOptions(e.status)}</select></td><td><input data-field="score" type="number" min="0" max="${e.scoreScale}" step="any" value="${e.score}" aria-label="Score for ${esc(e.title)}"><small>of ${e.scoreScale}</small></td><td><input data-field="chapters" type="number" min="0" step="1" value="${e.chapters}" aria-label="Chapters for ${esc(e.title)}"></td><td><button class="text-button" data-match>${esc(e.matchedTitle||'Find a match ↗')}</button><small>${esc(e.confidence)}</small><small>${esc(C.validate(e,settings).length?'Needs attention':'Ready')}</small></td><td><button class="button quiet" data-edit aria-label="Edit ${esc(e.title)}">Edit</button></td></tr>`).join('');$('empty-filter').hidden=!!rows.length;$('page-info').textContent=`${rows.length? page*50+1:0}–${Math.min(rows.length,page*50+50)} of ${rows.length.toLocaleString()}`;$('previous-page').disabled=page===0;$('next-page').disabled=(page+1)*50>=rows.length;$('selected-count').textContent=`${selected.size} selected`;$('select-all').checked=rows.length>0&&rows.every(e=>selected.has(e.key));$('save-project').disabled=!entries.length;$('to-defaults').disabled=!entries.length;$('load-summary').textContent=entries.length?`${entries.length.toLocaleString()} entries loaded locally`:'Choose a backup to get started';$('final-defaults').textContent=`${settings.destination} · Default score ${settings.defaultScore}/${settings.scoreScale} · ${settings.defaultStatus==='Unknown'?'Keep original status':C.labels[settings.defaultStatus]} · ${included.length.toLocaleString()} included · ${ready.length.toLocaleString()} ready · ${settings.policy==='review'?'Review required':'Invalid entries will be skipped'}`;$('destination-warning').textContent=settings.destination==='MyAnimeList'?'MyAnimeList receives whole-number scores and a separate rereading flag. Dates are not sent.':'AniList receives scores converted to 0–100. Empty dates preserve existing account dates.';}
function install(list,name){entries=list;originals=new Map(entries.map(e=>[e.key,structuredClone(e)]));selected.clear();page=0;changed();$('loaded-file').hidden=false;$('loaded-file').textContent=`${name} · ${entries.length.toLocaleString()} entries · processed on your device`;toast('Library loaded. Your original file has not changed.');}
async function busy(fn){if(controller)return;controller=new AbortController();$('busy').hidden=false;document.body.classList.add('busy-app');document.querySelectorAll('main,.topbar,.sidebar,#modal-content,#modal-actions').forEach(el=>el.inert=true);try{await fn(controller.signal);}catch(e){toast(controller.signal.aborted?'Operation cancelled.':e.message);}finally{controller=null;worker?.terminate();worker=null;$('busy').hidden=true;document.body.classList.remove('busy-app');document.querySelectorAll('main,.topbar,.sidebar,#modal-content,#modal-actions').forEach(el=>el.inert=false);C.markDuplicates(entries);render();}}
$('cancel-operation').onclick=()=>{controller?.abort();worker?.terminate();};
async function load(file){if(!file)return;if(file.size>C.MAX_BYTES){toast('The file exceeds 256 MB.');return;}await busy(async signal=>{const buffer=await file.arrayBuffer();signal.throwIfAborted();const parsed=await new Promise((resolve,reject)=>{worker=new Worker('./parser-worker.mjs',{type:'module'});signal.addEventListener('abort',()=>reject(new DOMException('Cancelled','AbortError')),{once:true});worker.onerror=()=>reject(Error('Unable to read this backup.'));worker.onmessage=({data})=>{if(data.error)reject(Error(data.error));else if(data.result)resolve(data.result);else if(data.progress)$('status').textContent=data.progress;};worker.postMessage({buffer,name:file.name},[buffer]);});install(parsed.entries.map(e=>C.initialize(e,settings)),file.name+' · '+parsed.format);navigate(1);});}
$('choose-file').onclick=e=>{e.stopPropagation();$('backup-input').click();};$('drop-zone').onclick=()=>$('backup-input').click();$('drop-zone').onkeydown=e=>{if(e.target===$('drop-zone')&&['Enter',' '].includes(e.key)){e.preventDefault();$('backup-input').click();}};$('backup-input').onchange=e=>{load(e.target.files[0]);e.target.value='';};$('drop-zone').ondragover=e=>e.preventDefault();$('drop-zone').ondrop=e=>{e.preventDefault();load(e.dataTransfer.files[0]);};
$('sample-button').onclick=()=>install(['A Lantern in Winter','Across the Quiet Sea','星の図書館','The Last Tea Shop','A Lantern in Winter'].map((title,i)=>({...C.emptyEntry(),title,author:['Mika Sato','Ren Aoki'][i%2],source:'Sample library',originalChapters:i*12,chapters:i*12,status:'Reading',scoreScale:10})), 'Sample library');$('to-defaults').onclick=()=>navigate(1);
for(const id of ['apply-score','apply-status','apply-continue'])$(id).onclick=async()=>{try{readSettings();C.applyDefaults(entries,settings,{score:id!=='apply-status',status:id!=='apply-score'});changed();toast('Defaults applied.');if(id==='apply-continue'){navigate(settings.instant?3:2);if(settings.autoMatch)await runAutomatic();}}catch(e){toast(e.message);}};
$('no-score').onclick=()=>{$('default-score').value=0;};document.querySelectorAll('[name=destination]').forEach(r=>r.onchange=()=>{settings.destination=r.value;entries=entries.map(e=>{const fresh=C.initialize(e,{...settings,defaultStatus:'Unknown'});return {...e,mediaId:fresh.mediaId,matchedTitle:fresh.matchedTitle,matchConfirmed:fresh.matchConfirmed,confidence:fresh.confidence,totalChapters:fresh.totalChapters,anilistId:fresh.anilistId,malId:fresh.malId,matchState:fresh.matchState,matchCandidates:[],matchQueries:[],matchError:''};});entries.forEach(e=>C.applyContentRating(e,null,false));originals=new Map(entries.map(e=>[e.key,structuredClone(e)]));syncSettings();changed();updateConnection();});for(const id of ['preserve-chapters','preserve-volumes','policy','instant','auto-match','missing-status','existing-policy'])$(id).onchange=()=>{readSettings();changed();};
for(const id of ['search','filter','sort','content-filter'])$(id).oninput=()=>{page=0;render();};$('previous-page').onclick=()=>{page--;render();};$('next-page').onclick=()=>{page++;render();};$('select-all').onchange=e=>{for(const row of filtered())e.target.checked?selected.add(row.key):selected.delete(row.key);render();};
$('library-body').onchange=e=>{const row=entries.find(x=>x.key===e.target.closest('tr')?.dataset.key);if(!row)return;if(e.target.hasAttribute('data-select')){e.target.checked?selected.add(row.key):selected.delete(row.key);render();}else if(e.target.dataset.field){row[e.target.dataset.field]=e.target.dataset.field==='status'?e.target.value:Number(e.target.value);changed();}};
$('library-body').onclick=e=>{const row=entries.find(x=>x.key===e.target.closest('tr')?.dataset.key);if(!row)return;if(e.target.closest('[data-edit]'))edit([row]);if(e.target.closest('[data-match]'))match(row);};
function chosen(){const a=entries.filter(e=>selected.has(e.key));if(!a.length)throw Error('Select at least one entry first.');return a;}
function edit(rows){const e=rows[0],bulk=rows.length>1;modal(bulk?`Edit ${rows.length} entries`:'Edit library entry',`<p class="help">${bulk?'Only checked fields are applied.':'Edits are local until you confirm an import.'}</p><div class="form-grid">${['title','status','score','chapters','volumes','startDate','finishDate','included','contentRating'].filter(k=>!bulk||k!=='title').map(k=>`<label>${bulk?`<input type="checkbox" id="use-${k}"> `:''}${esc(k==='contentRating'?'Content rating':k)}${k==='contentRating'?`<select id="edit-${k}">${C.contentRatings.map(r=>option(r,r==='Unknown'?'Unclassified':r,e[k])).join('')}</select>`:k==='status'?`<select id="edit-${k}">${statusOptions(e[k])}</select>`:k==='included'?`<select id="edit-${k}">${option('true','Included',String(e[k]))}${option('false','Excluded',String(e[k]))}</select>`:`<input id="edit-${k}" type="${['score','chapters','volumes'].includes(k)?'number':k.endsWith('Date')?'date':'text'}" value="${esc(e[k])}">`}</label>`).join('')}</div>${bulk?'':`<p class="help">Original progress: ${e.originalChapters} · Author: ${esc(e.author)} · Artist: ${esc(e.artist)} · Categories: ${esc(e.categories.join(', '))}</p><p class="help">Alternative titles: ${esc(e.alternativeTitles.join(' | '))}<br>Source: ${esc(e.source)}<br>Source URL: ${esc(e.url)}<br>Date added: ${esc(e.dateAdded)} · Updated: ${esc(e.lastUpdated)}<br>Known totals: ${e.totalChapters??'Unknown'} chapters / ${e.totalVolumes??'Unknown'} volumes<br>Destination ID: ${e.mediaId??'Unmatched'}</p><p class="help">${esc(C.validate(e,settings).join(' · '))}</p>`}`,[['Save edits',()=>{for(const row of rows)for(const k of ['title','status','score','chapters','volumes','startDate','finishDate','included','contentRating']){if(!$('edit-'+k)||(bulk&&!$('use-'+k).checked))continue;const v=$('edit-'+k).value;if(k==='title'&&v!==row.title){row.mediaId=null;row.matchConfirmed=false;row.matchedTitle='';row.confidence='Unmatched';row.matchState='Pending';row.matchCandidates=[];row.matchQueries=[];C.applyContentRating(row,null,false);}if(k==='contentRating'&&v!==row.contentRating)row.contentRatingSource='Manual';row[k]=['score','chapters','volumes'].includes(k)?Number(v):k==='included'?v==='true':v;}changed();$('modal').close();}]]);}
for(const [id,fn] of [['bulk-edit',a=>edit(a)],['toggle-inclusion',a=>{const on=a.some(e=>!e.included);a.forEach(e=>e.included=on);changed();}],['reset-selected',a=>{a.forEach(e=>Object.assign(e,structuredClone(originals.get(e.key))));changed();}],['keep-separate',a=>{a.forEach(e=>e.duplicateAcknowledged=true);changed();}],['merge-selected',a=>modal('Merge selected entries?',`<p>Keep “${esc(a[0].title)}”, combine maximum progress and categories, and exclude the other ${a.length-1} entries. Nothing is deleted.</p>`,[['Merge',()=>{C.merge(a);changed();$('modal').close();}]])]])$(id).onclick=()=>{try{fn(chosen());}catch(e){toast(e.message);}};
$('validate-button').onclick=()=>{C.markDuplicates(entries);render();toast(`${entries.filter(e=>e.included&&C.validate(e,settings).length).length} included entries need attention.`);};
const bridgeBase=['127.0.0.1','localhost'].includes(location.hostname)?location.origin:'http://127.0.0.1:43828';
async function connect(){const response=await fetch(bridgeBase+'/api/hello',{signal:AbortSignal.timeout(4000)});if(!response.ok)throw Error('Local connector unavailable.');bridge=await response.json();updateConnection();return bridge;}
function updateConnection(){$('connection-badge').textContent=bridge?.accounts?.[settings.destination]?'Signed in':bridge?'Connector running · Not signed in':'Connector not running';$('redirect-help').textContent='Redirect: '+(bridge?.redirect??'http://127.0.0.1:43828/oauth/callback');}
async function rpc(path,body,signal){if(!bridge)await connect();const r=await fetch(bridgeBase+'/api/'+path,{method:'POST',headers:{'content-type':'application/json','x-mapo-session':bridge.session},body:JSON.stringify({destination:settings.destination,...body}),signal});const data=await r.json();if(!r.ok)throw Error(data.error||'Connector request failed.');return data;}
function api(){return Object.fromEntries(['account','list','search','lookup','get','save'].map(method=>[method,async(arg,signal)=>{if(['account','list'].includes(method)){signal=arg;arg=undefined;}if(method==='list'&&bridge&&!/^2\.(?:[1-9]|[1-9][0-9])\./.test(bridge.version))return null;return (await rpc('rpc',{method,args:arg===undefined?[]:[arg],clientId:$('client-id').value},signal)).value;} ]));}
async function search(query,signal){if(!$('online-match').checked)throw Error('Enable optional online title matching first.');const key=settings.destination+':'+query;if(cache.has(key))return cache.get(key);const a=bridge?api():settings.destination==='AniList'?publicAniList:publicMyAnimeList;if(!a)throw Error('Connect the local connector to search MyAnimeList.');const rows=await a.search(query,signal);cache.set(key,rows);return rows;}
function match(e){modal('Confirm a destination match',`<div class="search-row"><input id="match-query" aria-label="Title to search" value="${esc(e.title)}"><button class="button" id="search-match">Search</button></div><div id="candidates"></div><hr><label>Verified ${settings.destination} manga ID<input id="manual-id" type="number" min="1" value="${e.mediaId??''}"></label><p class="help">Check the ID on the destination website before confirming. An ID from the other platform will not work.</p>`,[['Confirm entered ID',()=>{const id=+$('manual-id').value;if(!Number.isInteger(id)||id<1||id>2147483647)throw Error('Enter a valid manga ID.');Object.assign(e,{mediaId:id,matchedTitle:e.title,matchConfirmed:true,confidence:'Confirmed manually',totalChapters:null,totalVolumes:null});C.applyContentRating(e,null,false);changed();$('modal').close();}]]);const saved=e.matchCandidates??[];if(saved.length){$('candidates').innerHTML=saved.map((c,i)=>`<div class="candidate"><strong>${esc(c.title)}</strong><p>${esc(c.reason??'Saved candidate')} · ID ${c.id}</p><button class="button" data-saved-candidate="${i}">Confirm this manga</button></div>`).join('');$('candidates').onclick=ev=>{const b=ev.target.closest('[data-saved-candidate]');if(!b)return;acceptCandidate(e,saved[+b.dataset.savedCandidate],'Confirmed manually');changed();$('modal').close();};}$('search-match').onclick=()=>busy(async signal=>{const rows=await search($('match-query').value,signal);$('candidates').innerHTML=rows.length?rows.map((c,i)=>`<div class="candidate"><strong>${esc(c.title)}</strong><p>${esc(c.native)} · ${esc(c.author)} · ${esc(c.format)} · ${esc(c.year??'')} · ID ${c.id} · ${esc(c.contentRating??'Unknown')}</p><button class="button" data-candidate="${i}">Confirm this manga</button></div>`).join(''):'No results. Try an alternative title.';$('candidates').onclick=ev=>{const b=ev.target.closest('[data-candidate]');if(!b)return;const c=rows[+b.dataset.candidate];Object.assign(e,{mediaId:c.id,matchedTitle:c.title,matchConfirmed:true,confidence:'Confirmed manually',totalChapters:c.chapters,totalVolumes:c.volumes});C.applyContentRating(e,c);changed();$('modal').close();};});}
function renderMatching(info=matchSummary(entries)){stats('matching-stats',[['Matched automatically',info.matched],['Still to search',info.pending],['Needs review',info.uncertain],['No result',info.notFound]]);$('matching-progress').max=Math.max(1,info.total);$('matching-progress').value=info.total-info.pending;if(info.requests!==undefined)$('matching-message').textContent=(info.total-info.pending).toLocaleString()+' / '+info.total.toLocaleString()+' processed · '+info.requests+' searches this run · '+info.errors+' service errors';}
async function runAutomatic(retryUnresolved=false){for(const e of entries)if(e.included&&e.status==='Unknown'&&settings.missingStatus!=='Unknown')e.status=settings.missingStatus;if(retryUnresolved)cache.clear();$('online-match').checked=true;invalidate();let finished=false;$('cancel-operation').textContent='Pause matching';await busy(async signal=>{const searchApi=bridge?api():settings.destination==='AniList'?publicAniList:publicMyAnimeList;await matchLibrary(entries,searchApi,{destination:settings.destination,signal,retryUnresolved,cache,progress:info=>{renderMatching(info);$('status').textContent='Matching library: '+info.matched+' IDs found · '+info.pending+' left to search';}});finished=true;const summary=matchSummary(entries);$('matching-message').textContent='Matching complete: '+summary.matched+' matched, '+(summary.uncertain+summary.notFound+summary.errors)+' unresolved. You can import the matched entries now; editing is optional.';toast('Automatic matching complete. Sign in and prepare the matched library.');});$('cancel-operation').textContent='Cancel';return finished;}
$('match-all').onclick=()=>runAutomatic();$('auto-match-final').onclick=()=>runAutomatic();$('retry-unresolved').onclick=()=>runAutomatic(true);$('matching-report').onclick=()=>download('hikkoshi-unresolved.json',JSON.stringify({destination:settings.destination,entries:entries.filter(e=>e.included&&!e.matchConfirmed).map(e=>({title:e.title,state:e.matchState,reason:e.matchError||e.confidence,candidates:e.matchCandidates}))},null,2));

async function download(name,text,type='application/json'){if($('choose-save-location').checked&&window.showSaveFilePicker){const handle=await showSaveFilePicker({suggestedName:name});const writable=await handle.createWritable();await writable.write(text);await writable.close();}else{const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
function saveProject(){modal('Save your conversion project',`<p>This local file contains your library titles, progress and edits. Keep it somewhere private. Account tokens and secrets are never included.</p>`,[['Save project',async()=>{await download('hikkoshi-project.mapoproj',C.saveProject(entries,settings));$('modal').close();}]]);}
$('save-project').onclick=saveProject;$('save-project-bottom').onclick=saveProject;$('open-project').onclick=()=>$('project-input').click();$('project-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>C.MAX_BYTES)throw Error('Project exceeds 256 MB.');const p=C.loadProject(await f.text());settings=p.settings;syncSettings();install(p.entries,f.name);navigate(2);}catch(error){toast(error.message);}finally{e.target.value='';}};
$('export-csv').onclick=()=>modal('Preview review CSV',`<p>${entries.length.toLocaleString()} entries, including excluded rows and validation notes. This is a review report, not a platform import file.</p><pre style="overflow:auto;max-height:220px">${esc(C.reviewCsv(entries.slice(0,3),settings))}</pre>`,[['Save CSV',async()=>{await download('hikkoshi-review.csv','\uFEFF'+C.reviewCsv(entries,settings),'text/csv;charset=utf-8');$('modal').close();}]]);
$('connect-bridge').onclick=()=>connect().then(()=>toast('Local connector ready.')).catch(()=>toast('Start the local connector, then retry. Setup instructions explain how.'));
$('connector-help').onclick=()=>modal('Use the local connector',`<ol><li>Extract the Hikkoshi local ZIP supplied with this app.</li><li>Double-click <strong>Start Hikkoshi.cmd</strong>. Keep its window open.</li><li>Use <a href="http://127.0.0.1:43828" target="_blank" rel="noreferrer">Hikkoshi in your browser</a>, or click Connect local connector here.</li><li>Create your own AniList or MyAnimeList developer application. Set its redirect URL to <code>http://127.0.0.1:43828/oauth/callback</code>.</li><li>Enter the client ID (and AniList secret), then sign in.</li></ol><p>If your browser blocks a hosted page from connecting locally, use the local browser address above. Signing in never changes your library. Tokens are kept only in the running connector’s memory.</p>`);
$('sign-in').onclick=async()=>{const popup=window.open('about:blank','mapo-auth');try{const data=await rpc('auth/start',{clientId:$('client-id').value,secret:$('client-secret').value});$('client-secret').value='';if(!popup)throw Error('Allow the sign-in popup, then retry.');popup.location=data.url;$('cancel-auth').hidden=false;clearInterval(authTimer);authTimer=setInterval(async()=>{try{await connect();if(bridge.accounts[settings.destination]||!bridge.pending.includes(settings.destination)){clearInterval(authTimer);$('cancel-auth').hidden=true;invalidate();}}catch{}},1500);}catch(e){popup?.close();toast(e.message);}};
$('cancel-auth').onclick=async()=>{await rpc('auth/cancel',{});clearInterval(authTimer);$('cancel-auth').hidden=true;toast('Sign-in cancelled.');};$('sign-out').onclick=async()=>{try{await rpc('signout',{});await connect();invalidate();toast('Signed out.');}catch(e){toast(e.message);}};
function showPlan(){stats('plan-stats',[['Create',plan.entries.filter(e=>e.action==='Create').length],['Update',plan.entries.filter(e=>e.action==='Update').length],['Unchanged',plan.entries.filter(e=>e.action==='Unchanged').length],['Skipped',plan.skipped.length]]);$('plan-empty').hidden=true;$('plan-details').hidden=false;$('plan-details').innerHTML=plan.entries.map(e=>`<div class="plan-row"><strong>${esc(e.title)}</strong><span>${e.action} · ${esc(e.before?.status??'No entry')} → ${esc(e.after.status)} · chapters ${e.before?.chapters??0} → ${e.after.chapters} · score ${e.before?.score??0} → ${e.after.score}</span></div>`).join('')+plan.skipped.map(e=>`<div class="plan-row"><strong>${esc(e.title)}</strong><span>Skipped · ${esc(e.detail)}</span></div>`).join('');$('import-button').disabled=!plan.entries.some(e=>e.action!=='Unchanged');}
async function prepare(){if(settings.autoMatch&&matchSummary(entries).pending){navigate(3);if(!await runAutomatic())return;}if(!bridge?.accounts?.[settings.destination]){toast('The connector is running, but your account is not signed in. Complete Sign in in browser, then prepare the library.');$('sign-in').focus();return;}if(settings.policy==='review'&&entries.some(e=>e.included&&C.validate(e,settings).length)){toast('Resolve included entries that need attention, or choose a skip policy in Defaults.');return;}await busy(async signal=>{plan=await C.dryRun(api(),entries,settings,{signal,progress:m=>$('status').textContent=m});showPlan();toast('Dry run complete. No account changes were made.');});}
$('dry-run').onclick=prepare;$('retry-button').onclick=prepare;$('import-button').onclick=()=>modal('Confirm account changes',`<p>Apply ${plan.entries.filter(e=>e.action!=='Unchanged').length} changes to <strong>${esc(plan.account)}</strong> on ${esc(plan.destination)}? Existing scores and progress may be overwritten exactly as shown. No entries are deleted.</p>`,[['Confirm import',()=>{$('modal').close();busy(async signal=>{results=await C.execute(api(),plan,{signal,progress:m=>$('status').textContent=m});$('report-button').disabled=false;$('retry-button').disabled=false;$('import-button').disabled=true;toast(`Finished: ${results.filter(r=>r.result==='Succeeded').length} succeeded; ${results.filter(r=>r.result==='Failed').length} failed. Save the report for details.`);});}]]);
$('report-button').onclick=()=>download('hikkoshi-import-report.json',JSON.stringify({destination:settings.destination,results},null,2));$('clear-session').onclick=()=>modal('Clear this library?',`<p>Unsaved edits will be lost. Saved local files and your online account stay unchanged.</p>`,[['Clear library',()=>{entries=[];originals.clear();selected.clear();cache.clear();results=[];$('report-button').disabled=true;$('retry-button').disabled=true;invalidate();$('loaded-file').hidden=true;$('modal').close();navigate(0);}]]);
$('privacy-button').onclick=()=>modal('Your library stays yours',`<p>Backup extraction, editing and export run in this browser. Your backup is never sent to this website.</p><p>Optional matching sends searched titles to the official API. Dry runs and confirmed imports send only the entry IDs and fields required for the operation, through your local connector.</p><p>Libraries and tokens are not saved in browser storage. Projects and reports contain private library data; save them carefully. Only your appearance preference is remembered.</p>`);
$('theme').onchange=()=>{const theme=$('theme').value;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):theme;try{localStorage.setItem('mapo-theme',theme);}catch{}};try{$('theme').value=localStorage.getItem('mapo-theme')||'system';}catch{}$('theme').onchange();syncSettings();render();if(['127.0.0.1','localhost'].includes(location.hostname))connect().catch(()=>{});
